def maximal_square(m):
    R_, C = len(m), len(m[0]); dp = [[0] * (C + 1) for _ in range(R_ + 1)]; best = 0
    for i in range(R_):
        for j in range(C):
            if m[i][j] == "1":
                dp[i + 1][j + 1] = 1 + min(dp[i][j], dp[i][j + 1], dp[i + 1][j]); best = max(best, dp[i + 1][j + 1])
    return best * best

