int maximalSquare(vector<vector<char>>& m) {
    int R = m.size(), C = m[0].size(), best = 0; vector<vector<int>> dp(R + 1, vector<int>(C + 1, 0));
    for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) if (m[i][j] == '1') { dp[i+1][j+1] = 1 + min({dp[i][j], dp[i][j+1], dp[i+1][j]}); best = max(best, dp[i+1][j+1]); }
    return best * best;
}
